// Cloudflare Worker entry (only used when deployed with OpenNext/wrangler;
// ignored by local `next dev`).

// ts-ignore (not ts-expect-error): the file only exists after `opennextjs-cloudflare build`,
// so the import is an error on a fresh checkout and valid afterwards.
// eslint-disable-next-line @typescript-eslint/ban-ts-comment
// @ts-ignore - generated by `opennextjs-cloudflare build`
import openNextWorker from "./.open-next/worker.js";

type ExecCtx = { waitUntil(promise: Promise<unknown>): void };

// Cloudflare's static-assets layer ignores `Range`, but Safari/iOS will not play
// <video> unless the server answers byte-range requests with 206. Videos are
// routed here (wrangler `assets.run_worker_first`) and sliced by hand; they are
// small (< 1 MB), so buffering one in memory is fine.
const RANGE_ASSET = /\.(mp4|webm|mov)$/i;

async function serveRangeAsset(request: Request, env: { ASSETS?: { fetch(r: Request): Promise<Response> } }): Promise<Response | null> {
  const url = new URL(request.url);
  if (!env?.ASSETS || (request.method !== "GET" && request.method !== "HEAD") || !RANGE_ASSET.test(url.pathname)) return null;

  const assetRes = await env.ASSETS.fetch(new Request(request.url, { method: "GET" }));
  if (!assetRes.ok) return assetRes;

  const buf = await assetRes.arrayBuffer();
  const total = buf.byteLength;
  const headers = new Headers(assetRes.headers);
  headers.set("Accept-Ranges", "bytes");

  const range = request.headers.get("Range");
  const m = range ? /^bytes=(\d*)-(\d*)$/.exec(range.trim()) : null;
  if (!m || (m[1] === "" && m[2] === "")) {
    headers.set("Content-Length", String(total));
    return new Response(request.method === "HEAD" ? null : buf, { status: 200, headers });
  }

  let start: number;
  let end: number;
  if (m[1] === "") {
    // suffix range: last N bytes
    start = Math.max(0, total - Number(m[2]));
    end = total - 1;
  } else {
    start = Number(m[1]);
    end = m[2] === "" ? total - 1 : Math.min(Number(m[2]), total - 1);
  }
  if (start >= total || start > end) {
    headers.set("Content-Range", `bytes */${total}`);
    return new Response(null, { status: 416, headers });
  }
  headers.set("Content-Range", `bytes ${start}-${end}/${total}`);
  headers.set("Content-Length", String(end - start + 1));
  return new Response(request.method === "HEAD" ? null : buf.slice(start, end + 1), { status: 206, headers });
}

export default {
  async fetch(request: Request, env: unknown, ctx: ExecCtx): Promise<Response> {
    const rangeResponse = await serveRangeAsset(request, env as { ASSETS?: { fetch(r: Request): Promise<Response> } });
    if (rangeResponse) return rangeResponse;

    return (openNextWorker as { fetch: (r: Request, e: unknown, c: ExecCtx) => Promise<Response> }).fetch(
      request,
      env,
      ctx
    );
  },
};

